const items = $input.all();
if (!items || items.length === 0) {
  const wanted = $('Config').first().json['Topic Title'];
  throw new Error(`No topic found titled "${wanted}". It must exactly match a topic already created in Phase 1.`);
}
const topic = items[0].json;
return [{ json: { topic_id: topic.id, topic_title: topic.title, channel_id: topic.channel_id } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No video at stage "qc_passed" found for this topic. Run Phase 5 (phase5-qc.json) and get an overall_pass first.');
}
const video = items[0].json;
return [{ json: { id: video.id, channel_id: video.channel_id, script_id: video.script_id } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No "final" script found for this topic — Phase 2 must have completed with a Critic pass.');
}
const content = items[0].json.content;
const match = content.match(/\[HOOK\][^\n]*\n([\s\S]*?)(?:\n\n\[|$)/);
const hook = match ? match[1].trim() : content.slice(0, 300).trim();
return [{ json: { script_content: content, hook } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('Channel not found for this topic — data inconsistency, check the topics/channels tables.');
}
const channel = items[0].json;
return [{ json: { name: channel.name, niche: channel.niche, visual_style_notes: channel.visual_style_notes } }];

const topicTitle = $('Pick Topic Row').first().json.topic_title;
const hook = $('Pick Script Row').first().json.hook;
const channel = $('Pick Channel Info Row').first().json;

const system = `You are the Thumbnail agent. Generate 3 distinct thumbnail concepts — not 3
variations of the same idea.

Video title: ${topicTitle}
Video hook/topic: ${hook}
Channel visual style: ${channel.visual_style_notes}
Recent performance notes: No analytics history yet — this is this channel's first video through the pipeline.

For each concept, specify:
- The core visual (what's actually depicted)
- Text overlay, max 4 words — longer text underperforms
- Why this creates curiosity without misleading about the video's actual content —
  a thumbnail that overpromises kills retention, not just trust

Label them A = curiosity/question, B = dramatic visual, C = clean text-forward.
Recommend which to test first based on recent performance.

--- RESPONSE FORMAT ---

Respond with JSON only, no prose outside the JSON, matching exactly this shape:
{
  "concepts": [
    { "label": "A", "core_visual": string, "text_overlay": string, "why_not_misleading": string },
    { "label": "B", "core_visual": string, "text_overlay": string, "why_not_misleading": string },
    { "label": "C", "core_visual": string, "text_overlay": string, "why_not_misleading": string }
  ],
  "recommended_label": "A" | "B" | "C",
  "recommendation_reason": string
}`;

return [{ json: { system } }];

const raw = $input.first().json["Claude's Thumbnail JSON"] || '';
let parsed = null;
let parseError = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parseError = e.message;
}
const valid = parsed && Array.isArray(parsed.concepts) && parsed.concepts.length === 3 && parsed.concepts.every(c => c.label && c.core_visual && c.text_overlay) && parsed.recommended_label;
if (parseError || !valid) {
  throw new Error('Could not parse a valid Thumbnail JSON (needs a 3-item "concepts" array, each with label/core_visual/text_overlay, plus "recommended_label"). Paste error: ' + (parseError || 'missing/malformed fields'));
}

const videoId = $('Pick Video Row').first().json.id;
const rows = parsed.concepts.map(c => ({
  video_id: videoId,
  variant_label: `${c.label} — ${c.text_overlay} | ${c.core_visual}${c.label === parsed.recommended_label ? ` [RECOMMENDED: ${parsed.recommendation_reason || ''}]` : ''}`,
  storage_url: null,
  selected: c.label === parsed.recommended_label
}));

return [{ json: { rows, recommended_label: parsed.recommended_label } }];

const parsed = $('Parse Thumbnail JSON').first().json;
return [{ json: {
  result: `3 thumbnail concepts saved — videos.stage set to "thumbnail_ready". Recommended: ${parsed.recommended_label}.`,
  topic: $('Pick Topic Row').first().json.topic_title,
  video_id: $('Pick Video Row').first().json.id,
  recommended_label: parsed.recommended_label
} }];
